  aiChartName: string // имя чарта из ответа ИИ без имени (#253)
  aiShareSum: string // доли руки в ответе ИИ с такой суммой нормируются к единице
  ownBackFileMb: string // своя рубашка (#220): файл картинки — не больше, МБ
